import {evaluateOperatingPlan,operatingRecord} from './operating.mjs';
export function costError(code,t){return ({COST_PROJECT:t('先填写有效的项目单价、总量和最低募集额。','Complete a valid price, supply and minimum raise first.'),COST_BNB:t('填写非负 BNB 小数，最多 18 位小数；留空表示未知。','Use nonnegative decimal BNB with at most 18 places. Blank means unknown.'),COST_INTEGER:t('填写大于 0 的整数；数量可为 0。','Use a positive whole number; subscription quantity may be zero.'),COST_QUANTITY:t('不能超过项目公开认购总量。','Cannot exceed the public allocation.'),COST_RECIPIENTS:t('钱包数不能超过本次整枚认购单位数。','Recipient wallets cannot exceed the whole subscription units.')})[code]??t('请检查此项输入。','Check this input.');}
export function operatingResults(project,record,h){
 const {t,esc,b,n,note}=h,r=evaluateOperatingPlan(project.raw,record.inputs),v=(x,suffix=' BNB')=>x===null||x===undefined?'—':b(x)+suffix;
 if(r.errors.project)return note(costError(r.errors.project,t),'warning');
 const messages={unknown:t('成本或启动预算仍有未知项，当前不能判断是否覆盖。','Some costs or startup budget are unknown. Coverage is not yet assessed.'),'invalid-inputs':t('有输入未通过检查。请先修正后再使用结果。','Some inputs are invalid. Correct them before using the results.'),'below-success-condition':t('当前数量未达到发行成功条件，不产生成功发行服务费。','This quantity does not meet success conditions and earns no success issuance fee.'),'startup-gap':t('存在前置资金缺口。未来成功发行费不能替代当前启动预算。','There is a startup funding gap. Future success fees cannot replace available startup cash.'),'issuance-cost-shortfall':t('填写的成功路径成本高于理论发行费，需要补贴或降低成本；本页不会改动收费。','Entered success costs exceed the theoretical issuance fee. A subsidy or lower cost is needed; this page does not change fees.'),'covered-under-assumptions':t('成功路径在填写的假设下可覆盖成本；这不是已核实的 Gas、实际利润或上线就绪状态。','Entered assumptions cover success-path costs. This is not verified Gas, actual profit or launch readiness.')};
 const count=x=>x===null||x===undefined?'—':n(x);
 return `<section class="panel"><div class="section-heading"><h2>${t('计划概览','Plan overview')}</h2><span class="tag">${record.source==='illustrative-example'?t('假设算例','ILLUSTRATIVE'):t('手动 · 未核实','MANUAL · UNVERIFIED')}</span></div><div class="metrics"><div><span>${t('计划认购金额','Planned subscription amount')}</span><strong>${v(r.raisedWei)}</strong></div><div><span>${t('成功后理论发行费','Theoretical success fee')}</span><strong>${v(r.serviceFeeWei)}</strong></div><div><span>${t('填写的成功运营成本','Entered success operating costs')}</span><strong>${v(r.successCostWei)}</strong></div><div><span>${t('发行费减上述成本','Issuance fee less entered costs')}</span><strong class="${r.contributionWei!==null&&r.contributionWei<0n?'negative':''}">${v(r.contributionWei)}</strong></div></div><div id="cost-status" role="status">${note(messages[r.status],'warning')}</div><ol class="cash-timeline"><li><span>01</span><div><strong>${t('现有运营预算','Available operating budget')}</strong><p>${v(r.budgetWei)} · ${t('你填写的假设，不是钱包余额','Your assumption, not a wallet balance')}</p></div></li><li><span>02</span><div><strong>${t('收到发行费之前','Before issuance fees are available')}</strong><p>${t('需先承担','Cost to fund first')}: ${v(r.beforeFeeWei)}</p><p class="gold">${t('前置缺口','Startup gap')}: ${v(r.startupGapWei)}</p></div></li><li><span>03</span><div><strong>${t('成功结算后才分账','Split only after successful settlement')}</strong><p>${r.platformPercent}% → ${v(r.serviceFeeWei)}</p><small>${project.raw.type==='token'?t('达最低额后仍须等截止或售罄，并完成建池。','Reaching the minimum still requires expiry/sellout and successful liquidity.'):t('必须售罄成功后才分账。','The collection must sell out before splitting proceeds.')}</small></div></li><li><span>04</span><div><strong>${project.raw.type==='token'?t('后续固定与派发成本','Later fixed and delivery costs'):t('成功后的平台成本','Platform costs after success')}</strong><p>${v(r.afterFeeWei)}${project.raw.type==='token'?' + '+v(r.deliveryCostWei):''}</p><p>${t('完成路径总资金缺口','Total completion funding gap')}: ${v(r.completionGapWei)}</p></div></li></ol>${note(t('认购托管本金不作为平台运营现金。卖税、主动退出费和币价变化不计入本次基础测算。','Escrowed principal is not platform operating cash. Secondary tax, voluntary-exit fees and token-price changes are excluded from this base plan.'))}</section>
 <section class="panel"><h2>${t('失败路径也要有预算','Plan for the failure path')}</h2><dl class="facts"><div><dt>${t('成功发行服务费','Success issuance fee')}</dt><dd>0 BNB</dd></div><div><dt>${t('前置支出 + 失败追加支出','Pre-fee costs + failure extras')}</dt><dd>${v(r.failureCostWei)}</dd></div><div><dt>${t('失败路径资金缺口','Failure funding gap')}</dt><dd>${v(r.failureFundingGapWei)}</dd></div></dl><p>${t('未达门槛、NFT 未售罄、规则触发取消或建池宽限期失败时，按已确认规则退还有效认购本金，不收成功发行费，Gas 不退。这里只计算你填写的平台成本。','Below-minimum, unsold NFT, rule-triggered cancellation or expired liquidity grace follows the confirmed principal-refund rules: no success fee; Gas excluded. This section counts only entered platform costs.')}</p></section>
 <details class="panel"><summary>${t('覆盖参考与测算边界','Coverage reference & limits')}</summary><dl class="facts"><div><dt>${t('按当前成本假设的覆盖参考额','Coverage raise under current cost assumptions')}</dt><dd>${v(r.referenceRaiseWei)}</dd></div><div><dt>${t('参考认购单位数','Reference subscription units')}</dt><dd>${count(r.referenceUnits)}</dd></div><div><dt>${t('最高可募集','Maximum raise')}</dt><dd>${v(r.maxRaiseWei)}</dd></div><div><dt>${t('售罄时理论发行费','Theoretical sellout issuance fee')}</dt><dd>${v(r.maxServiceFeeWei)}</dd></div>${project.raw.type==='token'?`<div><dt>${t('计划数量所需理论最少身份数','Theoretical minimum identities for planned quantity')}</dt><dd>${count(r.theoreticalMinimumIdentities)}</dd></div><div><dt>${t('假设派发批次数','Assumed distribution batches')}</dt><dd>${count(r.batches)}</dd></div>`:''}</dl>${r.referenceAttainable===false?note(t('当前成本假设下，即使售罄也无法覆盖。本页不会自动提高价格、最低额或费率。','Under these cost assumptions, even sellout does not cover costs. This page does not automatically change price, minimum or fees.'),'warning'):''}<p>${project.raw.type==='nft'?t('NFT 只按全部售罄测算，领取者的网络 Gas 不在本表中；这不代表领取免费。填写的平台成本均为运营假设，不是链上报价。','NFT calculations require sellout. Claim-caller network Gas is outside this table; claims are not assumed free. Entered platform costs are operating assumptions, not chain quotes.'):t('覆盖参考保持你填写的钱包数和单批成本不变，不预测实际认购人数。身份数按当前整枚预览的 4% 上限推算，不是实际人数，也不能当作派发钱包数。所有参数都是运营假设，不是链上 Gas 报价。','The coverage reference holds entered wallet count and batch costs fixed. It does not forecast participants. Identity counts use the current whole-token preview’s 4% cap; they are neither observed people nor recipient-wallet counts. Inputs are operating assumptions, not chain Gas quotes.')}</p></details>`;
}
export function operatingPage({project,projects,record},h){
 const {t,esc,title,tag,link,btn,note}=h;
 const rec=operatingRecord(record,project.raw.type),inputs=rec.inputs,r=evaluateOperatingPlan(project.raw,inputs);
 const field=(key,label,help,{count=false}={})=>`<label class="field">${label}<input data-operating-field="${key}" id="cost-${key}" value="${esc(inputs[key])}" inputmode="${count?'numeric':'decimal'}" autocomplete="off" aria-describedby="cost-help-${key} cost-error-${key}" ${r.errors[key]?'aria-invalid="true"':''}><small id="cost-help-${key}">${help}</small><small class="error-text" id="cost-error-${key}">${r.errors[key]?costError(r.errors[key],t):''}</small></label>`;
 const options=projects.map(p=>`<option value="${esc(p.id)}" ${p.id===project.id?'selected':''}>${esc(p.raw.name||t('未命名草稿','Untitled draft'))} · ${p.raw.type==='nft'?'NFT':t('代币','Token')}${p.example?t(' · 示例',' · Example'):''}</option>`).join('');
 return `${title('OPERATING PLAN',t('先算清成本，<br>再安排发行。','Plan the cost.<br>Then plan the launch.'),t('管理侧的只读测算。所有预算和费用由你填写，不读取钱包，不改变项目价格、分账或最低募集额。','A read-only workspace calculator. You supply budget and costs; no wallet reads or changes to price, splits or minimum raise.'))}<div class="actions cost-project-row"><label class="field">${t('选择项目方案','Select a launch plan')}<select id="cost-project">${options}</select></label>${link('#/manage',t('返回项目管理 ↗','Back to workspace ↗'),'text-link')}</div><div class="cost-jumps actions">${btn('jump-section',t('填写假设 ↓','Edit assumptions ↓'),'secondary','data-target="operating-inputs"')}${btn('jump-section',t('结果与资金缺口 ↓','Results & funding gaps ↓'),'secondary','data-target="operating-results"')}</div>
 ${r.errors.project?note(costError(r.errors.project,t),'warning'):''}<div class="operating-layout"><section class="panel detail-section" id="operating-inputs" tabindex="-1"><div class="section-heading"><h2>${t('填写运营假设','Enter operating assumptions')}</h2>${tag(project.raw.type==='nft'?t('NFT · 平台 10%','NFT · Platform 10%'):t('代币 · 平台 5%','Token · Platform 5%'))}</div>${note(t('留空表示未知。填 0 仅代表你主动假设该项为零，不代表网络 Gas 免费或实际成本已核实。','Blank means unknown. Entering 0 is your explicit assumption, not free Gas or verified costs.'))}
 ${project.raw.type==='token'?`<label class="field">${t('计划认购数量','Planned subscription quantity')}<select data-operating-field="mode" id="cost-mode">${[['minimum',t('达到最低募集额','At minimum raise')],['sold-out',t('全部售罄','Sellout')],['custom',t('自定数量','Custom quantity')]].map(([v,l])=>`<option value="${v}" ${inputs.mode===v?'selected':''}>${l}</option>`).join('')}</select></label>${inputs.mode==='custom'?field('customUnits',t('计划认购代币枚数','Planned whole-token units'),t('仅用于测算，不代表已有认购。','Planning only; not existing subscriptions.'),{count:true}):''}`:note(t('NFT 成功路径按全部售罄计算；不足总量时不收成功发行费。','NFT success assumes sellout. Below full supply there is no success issuance fee.'))}
 <h3>${t('先有可用启动资金','Fund startup first')}</h3>${field('budgetBnb',t('可用平台运营预算 · BNB','Available platform operating budget · BNB'),t('手动计划值，不是从钱包读取的余额。','A manual planning value, not a wallet balance.'))}${field('beforeFeeBnb',t('收到可用发行费前的支出 · BNB','Costs before spendable issuance fees · BNB'),project.raw.type==='token'?t('包括平台承担的部署、建池和重试 Gas 等前置费用；不含 80% 建池本金，不从用户托管本金扣取。','Include platform-funded deployment, liquidity and retry Gas before fees are spendable. Exclude the 80% liquidity principal. Do not deduct from user escrow.'):t('包括平台承担的部署、内容固定和结算 Gas 等前置费用；不从用户托管本金扣取。','Include platform-funded deployment, content persistence and settlement Gas before fees are spendable. Do not deduct from user escrow.'))}
 <h3>${t('成功后的成本','Costs after success')}</h3>${field('afterFeeBnb',t('成功后的其他固定成本 · BNB','Other fixed costs after success · BNB'),t('不要重复计入前置支出；平台若补贴 NFT 领取，也填入这里。','Do not count pre-fee costs twice. Include any platform subsidy for NFT claims here.'))}
 ${project.raw.type==='token'?`${field('recipientCount',t('预计派发钱包数','Assumed recipient wallets'),t('钱包数不是代币枚数，也不一定等于 .ai 身份数。','Wallet count is not token quantity or necessarily .ai identity count.'),{count:true})}<div class="form-grid">${field('batchSize',t('每批钱包数 · 仅测算','Wallets per batch · Planning only'),t('不修改合约或执行器设置。','Does not change contract or executor settings.'),{count:true})}${field('batchCostBnb',t('每批费用假设 · BNB','Assumed cost per batch · BNB'),t('尚无真实模拟报价，请自行填写假设。','No real simulation quote exists. Enter an assumption.'))}</div>`:note(t('NFT 采用自助领取演示，领取者网络 Gas 未计入本表；这不代表 Gas 为零。','NFT self-claim caller Gas is outside this platform-cost table. This does not mean Gas is zero.'))}
 <h3>${t('失败时的额外支出','Additional failure costs')}</h3>${field('failureExtraBnb',t('失败追加支出 · BNB','Additional costs on failure · BNB'),t('只填前置支出以外的部分。失败不产生成功发行服务费。','Enter only costs beyond pre-fee expenses. Failure earns no success issuance fee.'))}
 <div class="actions">${btn('cost-example',t('填入假设算例','Use illustrative assumptions'),'secondary',`data-id="${esc(project.id)}"`)}${btn('cost-export',t('导出测算 JSON','Export planning JSON'),'text-link',`data-id="${esc(project.id)}"`)}${btn('cost-brief',t('交给 Agent 复核','Ask Agent to review'),'text-link',`data-id="${esc(project.id)}"`)}</div><p class="aside-help">${t('算例数字只是交互示范。测算数据与发行方案分开保存，不会改动已定稿指纹或经济规则。','Illustrative values demonstrate the interaction only. Cost plans are stored separately and do not alter sealed fingerprints or economic rules.')}</p></section><aside id="operating-results" class="detail-section" tabindex="-1">${operatingResults(project,rec,h)}</aside></div>`;
}
